func collectProcess(ctx context.Context, process *modalsdk.ContainerProcess) (stdout, stderr []byte, exitCode int, err error) {
	var wg sync.WaitGroup
	var stdoutErr, stderrErr error
	wg.Add(2)
	go func() {
		defer wg.Done()
		if process.Stdout == nil {
			return
		}
		stdout, stdoutErr = io.ReadAll(process.Stdout)
	}()
	go func() {
		defer wg.Done()
		if process.Stderr == nil {
			return
		}
		stderr, stderrErr = io.ReadAll(process.Stderr)
	}()
	exitCode, err = process.Wait(ctx, nil)
	if err != nil {
		// Modal wires exec stdio with context.Background(), so a canceled Wait
		// alone leaves ReadAll blocked. Close unblocks those reads.
		closeProcessStreams(process)
		wg.Wait()
		return nil, nil, 0, err
	}
	wg.Wait()
	if stdoutErr != nil {
		return nil, nil, 0, stdoutErr
	}
	if stderrErr != nil {
		return nil, nil, 0, stderrErr
	}
	if stdout == nil {
		stdout = []byte{}
	}
	if stderr == nil {
		stderr = []byte{}
	}
	return stdout, stderr, exitCode, nil
}

func closeProcessStreams(process *modalsdk.ContainerProcess) {
	if process.Stdout != nil {
		_ = process.Stdout.Close()
	}
	if process.Stderr != nil {
		_ = process.Stderr.Close()
	}
}

